perl -e '
use strict;
use warnings;
my $REPO = "/bench/repo";
my $INTERNAL = "$REPO/internal";

my @declarations;

sub get_package {
    my ($path) = @_;
    open my $fh, "<", $path or return undef;
    while (<$fh>) {
        if (/^package\s+(\w+)/) { close $fh; return $1; }
    }
    close $fh;
    return undef;
}

sub get_import_path {
    my ($path) = @_;
    my $rel = $path;
    $rel =~ s/^\Q$REPO\E\///;
    my @parts = split /\/, $rel;
    pop @parts;  # remove file name
    return "github.com/usememos/memos/" . join("/", @parts);
}

find("$INTERNAL", sub {
    my $path = $File::Find::name;
    return unless $path =~ /\.go$/ && $path !~ /_test\.go$/;
    my $pkg = get_package($path);
    my $import_path = get_import_path($path);
    open my $fh, "<", $path or return;
    my $line_num = 0;
    while (<$fh>) {
        $line_num++;
        if (/^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/) {
            my ($recv, $name) = ($1, $2);
            my $recv_type = undef;
            if (defined $recv) {
                $recv = $recv =~ s/^\s+|\s+$//gr;
                ($recv_type) = split /\s+/, $recv;
                $recv_type =~ s/^\*//;
            }
            push @declarations, {
                name => $name,
                recv => $recv_type,
                pkg => $pkg,
                import_path => $import_path,
                file => $path,
                line => $line_num,
            };
        }
    }
    close $fh;
});

print "Total declarations: " . scalar(@declarations) . "\n";
' 2>&1

