BEGIN { FS = "|" }
FNR == NR {
    import_path = $1
    recv = $2
    name = $3
    decl_file = $4
    decl_line = $5
    if (name == "init") next
    # package name = last segment of import path
    n = split(import_path, parts, "/")
    pkgname = parts[n]
    if (recv == "") {
        key = import_path SUBSEP name
        decl_type[key] = "func"
    } else {
        key = import_path SUBSEP recv SUBSEP name
        decl_type[key] = "method"
    }
    decl_path[key] = decl_file
    decl_lineno[key] = decl_line
    decl_import[key] = import_path
    decl_name[key] = name
    decl_recv[key] = recv
    decl_pkg[key] = pkgname
    keys[++nkeys] = key
    next
}
{
    pos1 = index($0, ":")
    pos2 = index(substr($0, pos1+1), ":")
    if (pos2 == 0) next
    filepath = substr($0, 1, pos1-1)
    lineno = substr($0, pos1+1, pos2-1)
    content = substr($0, pos1+pos2+1)

    if (match(content, /^[[:space:]]*func[[:space:]]+/)) next
    if (match(content, /^func[[:space:]]+/)) next

  # determine if file is in same package directory
    sub("^/bench/repo/", "", filepath)
    n = split(filepath, fparts, "/")
    file_import = "github.com/usememos/memos"
    for (i = 1; i < n-1; i++) {
        file_import = file_import "/" fparts[i]
    }

    for (i = 1; i <= nkeys; i++) {
        key = keys[i]
        name = decl_name[key]
        recv = decl_recv[key]
        pkgname = decl_pkg[key]
        import_path = decl_import[key]

        if (filepath == decl_path[key] && lineno == decl_lineno[key]) continue

        if (recv == "") {
            # qualified: pkgname.Name(
            pat = "(^|[^a-zA-Z0-9_])" pkgname "\\." name "[[:space:]]*\\("
            matched = match(content, pat)
            if (!matched && file_import == import_path) {
                # same-package unqualified call
                pat2 = "(^|[^a-zA-Z0-9_])" name "[[:space:]]*\\("
                matched = match(content, pat2)
            }
            if (matched) fanin[key]++
        } else {
            if (match(content, "\\." name "[[:space:]]*\\(")) {
                fanin[key]++
            }
        }
    }
}
END {
    for (i = 1; i <= nkeys; i++) {
        key = keys[i]
        printf "%d|%s|%s|%s|%s|%s\n", fanin[key]+0, decl_import[key], decl_recv[key], decl_name[key], decl_path[key], decl_lineno[key]
    }
}
